struct StreamCtx { void* current; };

// Base initialization (direct copy into target T)
template<typename T>
size_t StreamInit(T* target, StreamCtx& ctx) {
    memcpy(target, ctx.current, sizeof(T));
    ctx.current = (char*)ctx.current + sizeof(T);
    return sizeof(T);
}

// Specialization for initializing a dynamically sized pointer field (T**)
size_t StreamInit(char** data_ptr, StreamCtx& ctx) {
    size_t len;
    StreamInit(&len, ctx); // Read length marker

    // Allocate and initialize target buffer directly via dereference
    *data_ptr = (char*)malloc(len); 
    memcpy(*data_ptr, ctx.current, len);

    ctx.current = (char*)ctx.current + len;
    return len;
}
